+  ReviewUnit.make({
+    unitId: `unit-${String(index + 1).padStart(3, "0")}`,
+    paths: files.map((file) => file.path),
+    changedLines: files.reduce((total, file) => total + file.additions + file.deletions, 0),
+  });
